// Author: MiYu. One source terrain/ramp surface supplies render heights, location queries and native effects.
#include "world.h"
#include <algorithm>
#include <bit>
#include <cmath>
#include <cfloat>

namespace war3 {
void World::buildSurface() {
    auto& t=data_.terrain;surface_.reserve(t.corners.size());for(auto& c:t.corners)surface_.push_back((float(c.ground)-8192)/4+(int(c.cliff&15)-2)*128);std::vector<bool> raised(t.corners.size());
    for(unsigned y=0;y+1<t.height;++y)for(unsigned x=0;x+1<t.width;++x){std::array<size_t,4> at{size_t(y)*t.width+x,size_t(y+1)*t.width+x,size_t(y+1)*t.width+x+1,size_t(y)*t.width+x+1};std::array<unsigned,4> level;for(unsigned i=0;i<4;++i)level[i]=t.corners[at[i]].cliff&15;bool ramp=std::all_of(at.begin(),at.end(),[&](auto i){return (t.corners[i].flags&0x10)!=0;});if(ramp && !(level[0]==level[2] && level[1]==level[3])){auto base=*std::min_element(level.begin(),level.end());for(unsigned i=0;i<4;++i)if(level[i]==base)raised[at[i]]=true;}}
    for(size_t i=0;i<raised.size();++i)if(raised[i])surface_[i]+=64;
}
float World::height(WorldPoint point) const {
    auto& t=data_.terrain;float x=std::bit_cast<float>(point.x.bits()),y=std::bit_cast<float>(point.y.bits());if(!std::isfinite(x) || !std::isfinite(y))throw std::runtime_error("Non-finite height query");float offset=deformation(x,y);x=std::clamp((x-t.origin[0])/128,0.f,float(t.width-1));y=std::clamp((y-t.origin[1])/128,0.f,float(t.height-1));auto ix=std::min(unsigned(x),t.width-2),iy=std::min(unsigned(y),t.height-2);float u=x-ix,v=y-iy;auto at=size_t(iy)*t.width+ix;return (surface_[at]*(1-u)+surface_[at+1]*u)*(1-v)+(surface_[at+t.width]*(1-u)+surface_[at+t.width+1]*u)*v+offset;
}
namespace {
struct DeformationClock {double cycle,progress,fade;};
DeformationClock deformationClock(const TerrainDeformation& d,double now) {double age=std::max(0.,now-d.started),elapsed=d.duration>0?age/d.duration:1,completed=d.duration>0 && elapsed>0?std::ceil(elapsed)-1:0,cycle=elapsed-completed,fade=d.stopping && d.stopDuration>0?std::clamp(1-(now-d.stopStarted)/d.stopDuration,0.,1.):1;return {cycle,(completed+cycle)/d.count,fade};}
double craterHeight(const TerrainDeformation& d,double x,double y,double factor) {if(d.radius<=0)return 0;double distance=std::hypot(x-d.x,y-d.y);if(distance>d.radius)return 0;return -double(d.depth)*std::cos(1.5707963267948966*std::clamp(distance/d.radius,0.,1.))*factor;}
}
float World::deformation(float x,float y) const {
    if(deformations_.empty() && permanentHeights_.empty())return 0;auto& terrain=data_.terrain;double gx=std::clamp((double(x)-terrain.origin[0])/128,0.,double(terrain.width-1)),gy=std::clamp((double(y)-terrain.origin[1])/128,0.,double(terrain.height-1));unsigned ix=std::min(unsigned(gx),terrain.width-2),iy=std::min(unsigned(gy),terrain.height-2);double u=gx-ix,v=gy-iy;
    auto sample=[&](unsigned px,unsigned py){double sx=terrain.origin[0]+double(px)*128,sy=terrain.origin[1]+double(py)*128,total=permanentHeights_.empty()?0:permanentHeights_[size_t(py)*terrain.width+px];for(auto& d:deformations_){if(d.radius<=0)continue;if(d.kind==TerrainDeformationKind::Random){int x=int(px)-d.sampleLeft,y=int(py)-d.sampleBottom;if(x>=0 && y>=0 && x<d.sampleWidth && y<d.sampleHeight)total+=d.samples[size_t(y)*d.sampleWidth+x];continue;}auto clock=deformationClock(d,deformationTime_);double offset=0;if(d.kind==TerrainDeformationKind::Crater)offset=craterHeight(d,sx,sy,std::clamp(clock.cycle,0.,1.));else if(d.kind==TerrainDeformationKind::Wave){double time=clock.cycle*d.duration,head=d.travelTime>0?std::clamp(time/d.travelTime,0.,1.):1,tail=d.travelTime>0?std::clamp((time-d.trailTime)/d.travelTime,0.,1.):0,ax=d.x+double(d.dirX)*d.distance*tail,ay=d.y+double(d.dirY)*d.distance*tail,bx=d.x+double(d.dirX)*d.distance*head,by=d.y+double(d.dirY)*d.distance*head,dx=bx-ax,dy=by-ay,length=dx*dx+dy*dy,projection=length>0?std::clamp(((sx-ax)*dx+(sy-ay)*dy)/length,0.,1.):0,dist=std::hypot(sx-ax-projection*dx,sy-ay-projection*dy);if(dist<=d.radius)offset=-double(d.depth)*.5*(1+std::cos(3.141592653589793*dist/d.radius))*std::clamp((1-clock.cycle)*10,0.,1.);}else{double dist=std::hypot(sx-d.x,sy-d.y);if(dist<=double(d.radius)*(d.startRadius+(1-d.startRadius)*clock.progress)){offset=-double(d.depth)*std::sin(3.141592653589793*(double(d.spaceWaves)*std::clamp(dist/d.radius,0.,1.)+double(d.timeWaves)*clock.cycle))*(1-clock.progress);if(d.limitNegative)offset=std::min(0.,offset);}}total+=offset*clock.fade;}return total;};
    return float((sample(ix,iy)*(1-u)+sample(ix+1,iy)*u)*(1-v)+(sample(ix,iy+1)*(1-u)+sample(ix+1,iy+1)*u)*v);
}
float World::deformationBound() const {double bound=permanentBound_;for(auto& d:deformations_){auto clock=deformationClock(d,deformationTime_);bound+=d.kind==TerrainDeformationKind::Random?std::max(std::abs(double(d.randomMin)),std::abs(double(d.randomMax))):std::abs(double(d.depth))*(d.kind==TerrainDeformationKind::Ripple?std::abs(1-clock.progress):1);}return float(std::min(bound,double(FLT_MAX)/4));}
bool World::deformationIntersects(float minX,float minY,float maxX,float maxY) const {if(!permanentChunks_.empty()){auto& t=data_.terrain;unsigned columns=(t.width-2)/16+1,rows=(t.height-2)/16+1;int left=int(std::clamp(std::floor((double(minX)-128-t.origin[0])/2048),0.,double(columns))),right=int(std::clamp(std::floor((double(maxX)+128-t.origin[0])/2048),-1.,double(columns-1))),bottom=int(std::clamp(std::floor((double(minY)-128-t.origin[1])/2048),0.,double(rows))),top=int(std::clamp(std::floor((double(maxY)+128-t.origin[1])/2048),-1.,double(rows-1)));for(int y=bottom;y<=top;++y)for(int x=left;x<=right;++x)if(permanentChunks_[size_t(y)*columns+x])return true;}for(auto& d:deformations_){auto clock=deformationClock(d,deformationTime_);double radius=d.kind==TerrainDeformationKind::Ripple?std::max(0.,double(d.radius)*(d.startRadius+(1-double(d.startRadius))*clock.progress)):d.radius;radius+=128;double endX=d.x+(d.kind==TerrainDeformationKind::Wave?double(d.dirX)*d.distance:0),endY=d.y+(d.kind==TerrainDeformationKind::Wave?double(d.dirY)*d.distance:0);if(std::max(double(d.x),endX)+radius>=minX && std::min(double(d.x),endX)-radius<=maxX && std::max(double(d.y),endY)+radius>=minY && std::min(double(d.y),endY)-radius<=maxY)return true;}return false;}
void World::addDeformation(TerrainDeformation value) {if(value.duration==0 && ((value.kind==TerrainDeformationKind::Ripple && value.count==1) || value.kind==TerrainDeformationKind::Wave))return;if(deformations_.size()>=256)throw std::runtime_error("Terrain deformation budget exceeded");if(value.kind==TerrainDeformationKind::Random){auto& t=data_.terrain;int left=int(std::clamp(std::floor((double(value.x)-value.radius-t.origin[0])/128)+1,0.,double(t.width))),right=int(std::clamp(std::floor((double(value.x)+value.radius-t.origin[0])/128),-1.,double(t.width-1))),bottom=int(std::clamp(std::floor((double(value.y)-value.radius-t.origin[1])/128)+1,0.,double(t.height))),top=int(std::clamp(std::floor((double(value.y)+value.radius-t.origin[1])/128),-1.,double(t.height-1)));value.sampleLeft=left;value.sampleBottom=bottom;value.sampleWidth=std::max(0,right-left+1);value.sampleHeight=std::max(0,top-bottom+1);size_t used=0;for(auto& d:deformations_)used+=d.samples.size();size_t count=size_t(value.sampleWidth)*value.sampleHeight;if(count>16*1024*1024-used)throw std::runtime_error("Terrain random sample budget exceeded");value.samples.resize(count);value.nextUpdate=value.started;}deformations_.push_back(std::move(value));++deformationRevision_;}
void World::stopDeformation(std::uint32_t handle,double duration) {auto found=std::find_if(deformations_.begin(),deformations_.end(),[&](auto& d){return d.handle==handle;});if(found==deformations_.end())return;found->stopping=true;found->stopStarted=deformationTime_;found->stopDuration=duration;++deformationRevision_;}
void World::stopDeformations() {if(!deformations_.empty()){deformations_.clear();++deformationRevision_;}}
void World::bakeCrater(const TerrainDeformation& d,float factor) {if(d.radius<=0 || d.depth==0 || factor==0)return;auto& t=data_.terrain;int left=int(std::clamp(std::ceil((double(d.x)-d.radius-t.origin[0])/128),0.,double(t.width))),right=int(std::clamp(std::floor((double(d.x)+d.radius-t.origin[0])/128),-1.,double(t.width-1))),bottom=int(std::clamp(std::ceil((double(d.y)-d.radius-t.origin[1])/128),0.,double(t.height))),top=int(std::clamp(std::floor((double(d.y)+d.radius-t.origin[1])/128),-1.,double(t.height-1)));if(left>right || bottom>top)return;if(permanentHeights_.empty())permanentHeights_.resize(surface_.size());unsigned columns=(t.width-2)/16+1,rows=(t.height-2)/16+1;if(permanentChunks_.empty())permanentChunks_.resize(size_t(columns)*rows);bool wrote=false;for(int y=bottom;y<=top;++y)for(int x=left;x<=right;++x){auto offset=float(craterHeight(d,t.origin[0]+double(x)*128,t.origin[1]+double(y)*128,factor));if(offset!=0){wrote=true;permanentHeights_[size_t(y)*t.width+x]+=offset;permanentChunks_[size_t(std::min(unsigned(y),t.height-2)/16)*columns+std::min(unsigned(x),t.width-2)/16]=1;}}if(wrote)permanentBound_+=std::abs(double(d.depth)*factor);}
void World::updateDeformations(double now,const std::function<std::uint32_t()>& random) {
    double previous=deformationTime_;deformationTime_=now;if(deformations_.empty())return;bool changing=false;auto& terrain=data_.terrain;
    std::erase_if(deformations_,[&](auto& d){if(d.kind==TerrainDeformationKind::Random && now<d.nextUpdate)return false;bool stopped=d.stopping && now-d.stopStarted>=d.stopDuration,complete=!d.persistent && d.duration>0 && now-d.started>d.duration*d.count;if(d.kind==TerrainDeformationKind::Random){changing=true;if(!stopped){auto clock=deformationClock(d,complete?d.started+d.duration:now);double timeFade=std::clamp((1-clock.cycle)*10,0.,1.)*clock.fade;for(int y=0;y<d.sampleHeight;++y)for(int x=0;x<d.sampleWidth;++x){double sx=terrain.origin[0]+double(d.sampleLeft+x)*128,sy=terrain.origin[1]+double(d.sampleBottom+y)*128,dist=std::hypot(sx-d.x,sy-d.y);float value=0;if(d.radius>0 && dist<=d.radius){double ratio=2.f-std::bit_cast<float>(0x3f800000u|(random()&0x7fffffu)),edge=std::clamp((1-dist/d.radius)*5,0.,1.);value=float((double(d.randomMin)+(double(d.randomMax)-d.randomMin)*ratio)*edge*timeFade);}d.samples[size_t(y)*d.sampleWidth+x]=value;}d.nextUpdate=now+d.updateInterval;}}else changing=changing || d.duration>0 || d.stopping;if(complete && d.kind==TerrainDeformationKind::Crater && d.permanent){auto clock=deformationClock(d,stopped?previous:now);bakeCrater(d,float((stopped?std::clamp(clock.cycle,0.,1.):1)*clock.fade));}return stopped || complete;});if(changing)++deformationRevision_;
}
}
